#include "ui/editor_ui.hpp"
#include <imgui.h>
#include <imgui_internal.h>
#include <algorithm>
#include <cstdlib>
#include <filesystem>
namespace CrashEdit {
static void grid(ImDrawList*d,ImVec2 a,ImVec2 b){ImVec2 c((a.x+b.x)/2,a.y+(b.y-a.y)*.58f);float h=a.y+(b.y-a.y)*.3f;d->AddRectFilled(a,b,IM_COL32(25,30,38,255));d->AddRectFilled(a,ImVec2(b.x,h),IM_COL32(29,36,46,255));for(int i=-12;i<=12;++i)d->AddLine(ImVec2(c.x+i*42,h),ImVec2(c.x+i*115,b.y),IM_COL32(86,105,126,95));for(int i=1;i<=12;++i){float t=float(i)/12;float y=h+(b.y-h)*t*t;d->AddLine(ImVec2(a.x,y),ImVec2(b.x,y),IM_COL32(86,105,126,95));}ImVec2 o(c.x,h+(b.y-h)*.42f);d->AddLine(o,ImVec2(o.x+70,o.y),IM_COL32(210,85,80,255),2);d->AddLine(o,ImVec2(o.x,o.y-70),IM_COL32(100,190,125,255),2);d->AddLine(o,ImVec2(o.x-35,o.y+35),IM_COL32(95,145,225,255),2);}
void EditorUI::draw(){
 auto*v=ImGui::GetMainViewport();ImGui::SetNextWindowPos(v->WorkPos);ImGui::SetNextWindowSize(v->WorkSize);ImGui::SetNextWindowViewport(v->ID);
 ImGuiWindowFlags f=ImGuiWindowFlags_NoTitleBar|ImGuiWindowFlags_NoCollapse|ImGuiWindowFlags_NoResize|ImGuiWindowFlags_NoMove|ImGuiWindowFlags_NoBringToFrontOnFocus|ImGuiWindowFlags_NoNavFocus|ImGuiWindowFlags_NoBackground|ImGuiWindowFlags_MenuBar|ImGuiWindowFlags_NoDocking;
 ImGui::PushStyleVar(ImGuiStyleVar_WindowRounding,0);ImGui::PushStyleVar(ImGuiStyleVar_WindowBorderSize,0);ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding,ImVec2(0,0));ImGui::Begin("CrashEditHost",nullptr,f);ImGui::PopStyleVar(3);drawMenu();drawToolbar();auto id=ImGui::GetID("CrashEditDockSpace");ImGui::DockSpace(id,ImVec2(0,-24),ImGuiDockNodeFlags_PassthruCentralNode);ImGui::Separator();ImGui::TextUnformatted(status_.c_str());ImGui::End();
 static bool built=false;if(!built){built=true;ImGui::DockBuilderRemoveNode(id);ImGui::DockBuilderAddNode(id,ImGuiDockNodeFlags_DockSpace|ImGuiDockNodeFlags_PassthruCentralNode);ImGui::DockBuilderSetNodeSize(id,v->WorkSize);ImGuiID center=id;auto right=ImGui::DockBuilderSplitNode(center,ImGuiDir_Right,.23f,nullptr,&center);auto bottom=ImGui::DockBuilderSplitNode(center,ImGuiDir_Down,.27f,nullptr,&center);auto bottomRight=ImGui::DockBuilderSplitNode(bottom,ImGuiDir_Right,.32f,nullptr,&bottom);ImGui::DockBuilderDockWindow("3D Zone Editor",center);ImGui::DockBuilderDockWindow("Resource Hierarchy",right);ImGui::DockBuilderDockWindow("Properties",bottomRight);ImGui::DockBuilderDockWindow("Console / Diagnostics",bottom);ImGui::DockBuilderDockWindow("Asset Browser",bottom);ImGui::DockBuilderFinish(id);}
 drawHierarchy();drawViewport();drawBottom();
 if(openDialog_){ImGui::OpenPopup("Open Workspace");openDialog_=false;}if(ImGui::BeginPopupModal("Open Workspace",nullptr,ImGuiWindowFlags_AlwaysAutoResize)){ImGui::TextWrapped("Choose a folder containing CrashEdit project files or extracted game data.");ImGui::InputText("Folder path",path_,sizeof(path_));if(ImGui::Button("Open")){std::string e;if(workspace_.open(std::filesystem::u8path(path_),e)){status_="Workspace opened: "+workspace_.rootPath().string();ImGui::CloseCurrentPopup();}else status_=e;}ImGui::SameLine();if(ImGui::Button("Cancel"))ImGui::CloseCurrentPopup();ImGui::EndPopup();}
 if(about_){ImGui::OpenPopup("About CrashEdit");about_=false;}if(ImGui::BeginPopupModal("About CrashEdit",nullptr,ImGuiWindowFlags_AlwaysAutoResize)){ImGui::Text("CrashEdit — cross-platform rewrite");ImGui::Text("C++20 / Dear ImGui / GLFW / OpenGL");ImGui::TextWrapped("Initial editor shell; original Crash formats and renderer are being ported incrementally.");if(ImGui::Button("Close"))ImGui::CloseCurrentPopup();ImGui::EndPopup();}
}
void EditorUI::drawMenu(){if(!ImGui::BeginMenuBar())return;if(ImGui::BeginMenu("File")){if(ImGui::MenuItem("Open Workspace...","Ctrl+O"))openDialog_=true;if(ImGui::MenuItem("Close Workspace",nullptr,false,workspace_.isOpen())){workspace_.close();status_="Workspace closed.";}ImGui::Separator();if(ImGui::MenuItem("Exit"))std::exit(0);ImGui::EndMenu();}if(ImGui::BeginMenu("Edit")){ImGui::MenuItem("Undo","Ctrl+Z",false,false);ImGui::MenuItem("Redo","Ctrl+Y",false,false);ImGui::EndMenu();}if(ImGui::BeginMenu("View")){ImGui::MenuItem("Properties",nullptr,&properties_);ImGui::MenuItem("Console / Diagnostics",nullptr,&console_);ImGui::MenuItem("Asset Browser",nullptr,&assets_);ImGui::EndMenu();}if(ImGui::BeginMenu("Help")){if(ImGui::MenuItem("About"))about_=true;ImGui::EndMenu();}ImGui::EndMenuBar();}
void EditorUI::drawToolbar(){ImGui::BeginChild("Toolbar",ImVec2(0,34),ImGuiChildFlags_Borders,ImGuiWindowFlags_NoScrollbar);if(ImGui::Button("Open Workspace"))openDialog_=true;ImGui::SameLine();ImGui::BeginDisabled(!workspace_.isOpen());ImGui::Button("Save");ImGui::SameLine();ImGui::Button("Import");ImGui::SameLine();ImGui::Button("Export");ImGui::EndDisabled();ImGui::SameLine();auto n=workspace_.isOpen()?workspace_.rootPath().filename().string():"None";ImGui::TextDisabled("| Workspace: %s",n.c_str());ImGui::EndChild();}
void EditorUI::drawHierarchy(){ImGui::Begin("Resource Hierarchy");if(ImGui::Button("Open Folder..."))openDialog_=true;ImGui::Separator();if(!workspace_.isOpen())ImGui::TextDisabled("No workspace loaded.");else{ImGui::TextDisabled("%s",workspace_.rootPath().string().c_str());for(const auto&n:workspace_.resources())drawNode(n);}ImGui::End();}
void EditorUI::drawNode(const ResourceNode&n){std::string label=(n.isDirectory?"[+] ":"    ")+n.name;if(n.isDirectory){bool open=ImGui::TreeNodeEx(label.c_str(),ImGuiTreeNodeFlags_SpanAvailWidth|(n.children.empty()?ImGuiTreeNodeFlags_Leaf:0));if(ImGui::IsItemClicked())workspace_.selectResource(n.path.string());if(open){for(const auto&c:n.children)drawNode(c);ImGui::TreePop();}}else if(ImGui::Selectable(label.c_str(),workspace_.selectedResource()==n.path.string(),ImGuiSelectableFlags_SpanAvailWidth)){workspace_.selectResource(n.path.string());nsfValid_=false;if(n.path.extension()==".nsf"||n.path.extension()==".NSF"){std::string e;if(nsf_.load(n.path,e)){nsfValid_=true;status_="NSF loaded: "+std::to_string(nsf_.chunks().size())+" chunks";}else status_="NSF load failed: "+e;}else status_="Selected: "+n.name+" ("+n.kind+")";}}
void EditorUI::drawViewport(){ImGui::Begin("3D Zone Editor");ImGui::TextDisabled("SCENE VIEW | Perspective | Grid");auto a=ImGui::GetCursorScreenPos();auto s=ImGui::GetContentRegionAvail();s.x=std::max(s.x,100.f);s.y=std::max(s.y,100.f);ImGui::InvisibleButton("ZoneViewportCanvas",s);grid(ImGui::GetWindowDrawList(),a,ImVec2(a.x+s.x,a.y+s.y));ImGui::GetWindowDrawList()->AddText(ImVec2(a.x+16,a.y+14),IM_COL32(205,211,220,255),workspace_.isOpen()?"Workspace loaded — renderer integration is next":"No zone loaded — open a workspace");ImGui::End();}
void EditorUI::drawBottom(){if(console_){ImGui::Begin("Console / Diagnostics",&console_);ImGui::TextUnformatted("[info] Startup complete.");ImGui::TextUnformatted("[todo] Port NSF / NSD resource readers and renderer.");ImGui::End();}if(properties_){ImGui::Begin("Properties",&properties_);if(workspace_.selectedResource().empty())ImGui::TextDisabled("Select a resource to inspect its properties.");else{std::filesystem::path p(workspace_.selectedResource());std::error_code e;ImGui::Text("Name: %s",p.filename().string().c_str());ImGui::Text("Path: %s",p.string().c_str());ImGui::Text("Extension: %s",p.extension().string().c_str());if(std::filesystem::is_regular_file(p,e)){auto z=std::filesystem::file_size(p,e);if(!e)ImGui::Text("Size: %llu bytes",(unsigned long long)z);}if(nsfValid_){ImGui::Separator();ImGui::Text("NSF chunks: %llu",(unsigned long long)nsf_.chunks().size());ImGui::Text("Compressed: %llu",(unsigned long long)nsf_.compressedChunkCount());for(std::size_t i=0;i<nsf_.chunks().size();++i){auto&c=nsf_.chunks()[i];ImGui::BulletText("%03llu ID %04X Type %04X%s",(unsigned long long)i,(unsigned)c.chunkId,(unsigned)c.type,c.wasCompressed?" [compressed]":"");}}}ImGui::End();}if(assets_){ImGui::Begin("Asset Browser",&assets_);ImGui::TextDisabled("Asset thumbnails and Crash resource filters are planned.");ImGui::End();}}
}
